"""
DictDataBase - a fast document oriented database, using json or compressed json
files as the storage backend.

Usage:

>>> import dictdatabase as DDB
>>> DDB.at("users").create({"u1": {"name": "Ben"}}, force_overwrite=True)
>>> DDB.at("users", key="u1").read()
{'name': 'Ben'}

The configuration is available as `DDB.config`, e.g.
`DDB.config.storage_directory = "./ddb_storage"`.
"""

# The configuration must be imported first, since every other module depends on
# the config object being accessible as an attribute of this package.
from .configuration import Confuguration, config  # noqa: F401, I001

# Import all submodules, so that they are accessible as attributes of this
